INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Notebook immer leistungsstärker als ein Desktop-PC ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Konfiguration"}, {"text": "Ja", "correct": false, "because": "Zu vereinfacht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich ein Notebook für ein IT-System auswähle?', 3, '[{"text": "Leistung", "correct": true, "because": "Bestimmt Einsatz"}, {"text": "Schnellste Installation", "correct": false, "because": "Qualität zählt"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind bei einem Notebook entscheidend?', 5, '[{"text": "Prozessor", "correct": true, "because": "Bestimmt Rechenleistung"}, {"text": "Akku", "correct": true, "because": "Ermöglicht Mobilität"}, {"text": "Büromöbel", "correct": false, "because": "Kein Bestandteil"}, {"text": "Farbanalyse", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Notebook hat einen eingebauten Bildschirm. b) Es ist immer schwerer als ein Desktop-PC.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Leichter möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein Notebook für ein IT-System auswähle?', 4, '[{"text": "Prozessorleistung", "correct": false, "because": "Bestimmt Einsatz"}, {"text": "Akkulaufzeit", "correct": false, "because": "Sichert Mobilität"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Notebook immer eine Festplatte benötigt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch SSD möglich"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Notebook in einem IT-System?', 3, '[{"text": "Mobilität", "correct": true, "because": "Ermöglicht flexiblen Einsatz"}, {"text": "Schnellste Einrichtung", "correct": false, "because": "Funktion zählt"}, {"text": "Weniger Leistung", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale sind bei einem Notebook entscheidend?', 5, '[{"text": "Gewicht", "correct": true, "because": "Beeinflusst Mobilität"}, {"text": "Bildschirmgröße", "correct": true, "because": "Bestimmt Nutzung"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Notebook hat eine eingebaute Tastatur. b) Es ist immer teurer als ein Desktop-PC. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um ein Notebook effektiv einzusetzen?', 4, '[{"text": "Betriebssystem", "correct": false, "because": "Ermöglicht Betrieb"}, {"text": "Netzwerkanbindung", "correct": false, "because": "Fördert Kommunikation"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Notebook immer leistungsstärker als ein Desktop-PC?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Konfiguration"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Notebook?', 4, '[{"text": "Portabilität", "correct": true, "because": "Flexibler Einsatz"}, {"text": "Integrierte Komponenten", "correct": true, "because": "Alles in einem"}, {"text": "Schnellere Installation", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Notebook nur für den privaten Gebrauch geeignet ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch geschäftlich"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um ein Notebook für ein IT-System auszuwählen?', 3, '[{"text": "Prozessorleistung", "correct": true, "because": "Bestimmt Einsatz"}, {"text": "Günstigster Preis", "correct": false, "because": "Qualität wichtiger"}, {"text": "Bunte Optik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Notebook hat einen Akku. b) Es benötigt immer eine externe Tastatur.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tastatur integriert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei einem Notebook?', 5, '[{"text": "Akkulaufzeit", "correct": true, "because": "Sichert Mobilität"}, {"text": "Speicherkapazität", "correct": true, "because": "Bestimmt Nutzung"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich ein Notebook für ein IT-System auswähle?', 3, '[{"text": "RAM-Größe", "correct": false, "because": "Beeinflusst Leistung"}, {"text": "Gewicht", "correct": false, "because": "Bestimmt Mobilität"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Benötigt ein Notebook immer eine externe Stromversorgung?', 3, '[{"text": "Nein", "correct": true, "because": "Akku integriert"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Notebook immer langsamer als ein Desktop-PC ist?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Hardware"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für ein Notebook?', 4, '[{"text": "Mobilität", "correct": true, "because": "Kernmerkmal"}, {"text": "Schnellste Einrichtung", "correct": false, "because": "Funktion zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
